function Specs(){const{bike}=useContext(Ctx);return <SpecsForBike key={bikeScope(bike)}/>;}
function SpecsForBike(){const{bike}=useContext(Ctx),[count,setCount]=useState<number|null>(null),[query,setQuery]=useState(''),[found,setFound]=useState<Claim[]|null>(null),[busy,setBusy]=useState(false),[notice,setNotice]=useState('');
 useEffect(()=>{let active=true;setCount(null);setFound(null);setQuery('');setNotice('');if(bike)api<Claim[]>(`/api/claims?bike_id=${bike.id}`).then(r=>{if(!active)return;setCount(r.length);setNotice(r.length?'':`Verified specs for the ${bike.model_year} ${bike.model} aren’t loaded yet. Ask BAK can still help, and it tells you when a number isn’t published.`);}).catch(e=>{if(active)setNotice(errorText(e));});return()=>{active=false;};},[bike?.id]);
 async function search(){if(!bike||!query.trim()||busy)return;setBusy(true);setNotice('');try{const r=await api<Claim[]>(`/api/claims/search?bike_id=${bike.id}&q=${encodeURIComponent(query.trim())}`);setFound(r);if(!r.length)setNotice('Nothing verified matches that for this exact bike. Try the wording a service manual would use.');}catch(e){setNotice(errorText(e));}finally{setBusy(false);}}
 return <Page title="Specs and parts"><BikeSelect/>{count!==null&&count>0&&<Card><Copy strong>Verified specifications</Copy><Copy>{count} verified records for this exact bike. Coverage is not complete; a value that isn’t here is unknown, not zero.</Copy><Field editable={!busy} label="Search" value={query} onChangeText={setQuery} returnKeyType="search" onSubmitEditing={()=>void search()} placeholder="Rear axle nut torque, valve clearance…"/><Button disabled={busy||!query.trim()} title={busy?'Searching…':'Search'} onPress={()=>void search()}/></Card>}<Notice text={notice}/>{(found??[]).map(c=><Card key={c.id}><Copy strong>{factLabel(c)}</Copy><Text selectable style={{color:colors.text,fontSize:16,lineHeight:24}}>{c.statement}</Text><Copy>{c.model_year} · {c.variant} · {c.region}{'\n'}{c.source_locator}</Copy><LinkAction title="Open source" onPress={()=>{if(c.source_url.startsWith('https://'))void Linking.openURL(c.source_url).catch(e=>setNotice(errorText(e)));}}/></Card>)}<PartsCatalogCard bike={bike}/></Page>}
/** While Ask BAK works (usually 20-40 s): what it is doing and how long it has been, so a long answer never looks stuck. */
/** BAK MX's own legal and support pages. A build setting may only point somewhere on bakmx.com, so a value copied from
 *  another app (BAK Tech EMOTO is a separate product and subscription) can never send riders to the wrong support page. */
const mxPage=(env:string|undefined,page:'privacy'|'terms'|'support')=>env&&/^https:\/\/(www\.)?bakmx\.com\//.test(env)?env:`https://bakmx.com/${page}`;
/** Optional VIN: checks the picked year (and maker where the code is well known) against the frame. Stays on the rider's bike record; never sent to the AI. */
function VinField({value,onChange,bike,disabled}:{value:string;onChange:(v:string)=>void;bike:{manufacturer:string;model_year:number};disabled?:boolean}){const check=checkVin(value,bike);return <View style={{gap:4}}><Field editable={!disabled} label="VIN (optional)" placeholder="17 characters, on the steering head" autoCapitalize="characters" autoCorrect={false} maxLength={20} value={value} onChangeText={v=>onChange(cleanVin(v))}/>{check&&<Text style={{color:check.level==='ok'?'#9fd3ae':check.level==='check'?'#e9c77b':'#f0b4bd',fontSize:13,lineHeight:18}}>{check.text}</Text>}</View>;}
const SERVICE_QUICK=['Engine oil','Oil filter','Air filter','Spark plug','Valve check','Top end','Fork service','Shock service','Chain & sprockets','Brake pads','Coolant','Clutch'];
function ServiceRow({e,hoursNow,onDelete}:{e:ServiceEvent;hoursNow:number|null;onDelete:()=>void}){const [open,setOpen]=useState(false);const d=e.performed_at.slice(0,10);
 return <View style={{borderBottomWidth:StyleSheet.hairlineWidth,borderBottomColor:'#2a2f39'}}><Pressable accessibilityRole="button" accessibilityState={{expanded:open}} onPress={()=>setOpen(!open)} style={{paddingVertical:13,flexDirection:'row',alignItems:'center',gap:12}}>
  <View style={{flex:1,gap:2}}><Text style={{color:colors.text,fontSize:16,fontWeight:'600'}}>{e.category}</Text><Text style={{color:'#adb5c1',fontSize:13}}>{formatValue(d,false)||d} · {e.engine_hours??'?'} h{e.next_due_hours!==null?` · next at ${e.next_due_hours} h`:''}</Text></View>
  <Icon name={open?'chevronDown':'chevronRight'} size={17} color="#7d8593"/></Pressable>
  {open&&<View style={{gap:6,paddingBottom:12}}><Copy>{e.notes||'No notes.'}</Copy>{e.next_due_hours!==null&&<Copy>Next at {e.next_due_hours} h{hoursNow!==null?` · ${Math.max(0,e.next_due_hours-hoursNow).toFixed(1)} h to go`:''}{e.interval_source?` · ${e.interval_source}`:''}</Copy>}<LinkAction muted arrow={false} title="Delete entry" onPress={onDelete}/></View>}
 </View>;}
function WorkingLine(){const [t,setT]=useState(0);useEffect(()=>{const id=setInterval(()=>setT(x=>x+1),1000);return()=>clearInterval(id);},[]);const stage=t<6?'Reading your build sheet':t<14?'Checking the manual and known issues for your bike':t<45?'Writing your answer':'Still writing. Long answers can take up to a minute';return <Text accessibilityLiveRegion="polite" style={{color:'#b2b9c4',fontSize:12.5,paddingLeft:18,paddingTop:8}}>{stage}… {t}s</Text>;}
function Account(){const{session,bike}=useContext(Ctx),[notice,setNotice]=useState(''),[busy,setBusy]=useState(false),[confirm,setConfirm]=useState('');async function task(action:()=>Promise<unknown>,success?:string){setBusy(true);try{await action();if(success)setNotice(success);}catch(e){if((e as {userCancelled?:boolean}).userCancelled)setNotice('Purchase cancelled.');else setNotice(errorText(e));}finally{setBusy(false);}}async function exportData(){const data=await api('/api/account/export');const file=new File(Paths.cache,'bakmx-account-export.json');try{file.create({overwrite:true});file.write(JSON.stringify({account:data,device_local_progress:exportProgress(session.user.id)},null,2));if(!await Sharing.isAvailableAsync())throw new Error('File sharing is unavailable on this device.');await Sharing.shareAsync(file.uri,{mimeType:'application/json',UTI:'public.json'});}finally{if(file.exists)file.delete();}}return <Page title="Account"><Copy>{session.user.email}</Copy><Notice text={notice}/><ProfileCard/><PlansCard/><FeedbackCard bike={bike}/><TileGrid><Tile icon="export" title="Export my data" detail="A copy of your Garage, chats and logs" onPress={()=>{if(!busy)void task(exportData);}}/>{([['Privacy policy',mxPage(process.env.EXPO_PUBLIC_PRIVACY_URL,'privacy'),'verified'],['Terms of service',mxPage(process.env.EXPO_PUBLIC_TERMS_URL,'terms'),'document'],['Contact support',mxPage(process.env.EXPO_PUBLIC_SUPPORT_URL,'support'),'mail']] as [string,string|undefined,IconName][]).map(([label,url,icon])=><Tile key={label} icon={icon} title={label} detail={label==='Contact support'?'Questions, bugs, billing':'Opens in your browser'} onPress={()=>url?void Linking.openURL(url).catch(e=>setNotice(errorText(e))):setNotice(`${label} is not configured in this build.`)}/>)}<Tile icon="signout" title="Sign out" detail={session.user.email??''} onPress={()=>{if(!busy)void task(async()=>{const r=await supabase!.auth.signOut();if(r.error)throw r.error;});}}/></TileGrid><Card><Copy strong>Delete account</Copy><Copy>Deletion removes your Garage, conversations and service history. Cancel your Apple or Google subscription in the store before deleting your account.</Copy><Field label="Type DELETE to confirm" placeholder="DELETE" autoCapitalize="characters" value={confirm} onChangeText={setConfirm}/><Button secondary disabled={busy||confirm!=='DELETE'} title="Permanently delete account" onPress={()=>Alert.alert('Permanently delete account?','This action cannot be undone. Export your data first if you need a copy.',[{text:'Cancel',style:'cancel'},{text:'Delete account',style:'destructive',onPress:()=>void task(async()=>{await api('/api/account','DELETE',{confirmation:'DELETE'});clearProgress(session.user.id);await supabase!.auth.signOut({scope:'local'});})}])}/></Card></Page>}

/** The clip a rider sent with a question, for tap-a-time-to-see-the-frame in BAK's answer. */
function clipOf(m?:Message){return m?.role==='user'&&m.media?.kind==='clip'&&m.photos?.length&&m.media.frames.length===m.photos.length?{times:m.media.frames,photos:m.photos}:null;}

/** "What are you showing BAK?" One tap so BAK knows what to look at; slow motion only for clips. */
function FocusChips({focus,onFocus,slowmo,onSlowmo,tracks,where,onWhere}:{focus:CoachFocus|null;onFocus:(f:CoachFocus|null)=>void;slowmo:boolean|null;onSlowmo:(v:boolean)=>void;tracks:string[];where:string|null;onWhere:(t:string|null)=>void}){
 const chip=(key:string,label:string,on:boolean,press:()=>void)=><Pressable key={key} accessibilityRole="button" accessibilityState={{selected:on}} onPress={press} hitSlop={4} style={({pressed})=>({paddingHorizontal:12,paddingVertical:6,borderRadius:15,borderWidth:1,borderColor:on?colors.accent:'#2f3540',backgroundColor:on?'rgba(106,164,255,0.16)':'transparent',opacity:pressed?0.7:1})}><Text style={{color:on?'#ffffff':'#c9cfd9',fontSize:13,fontWeight:on?'700':'500'}}>{label}</Text></Pressable>;
 return <View style={{gap:6,paddingTop:6}}>
  <Text style={{color:'#7d8593',fontSize:12}}>What are you showing BAK?</Text>
  <ScrollView horizontal showsHorizontalScrollIndicator={false} keyboardShouldPersistTaps="handled" contentContainerStyle={{gap:6}}>
   {COACH_FOCUS.map(f=>chip(f.id,f.label,focus===f.id,()=>onFocus(focus===f.id?null:f.id)))}
   {slowmo!==null&&<View style={{width:1,backgroundColor:'#2f3540',marginHorizontal:4}}/>}
   {slowmo!==null&&chip('slowmo','Slow motion',slowmo,()=>onSlowmo(!slowmo))}
  </ScrollView>
  {tracks.length>0&&<><Text style={{color:'#7d8593',fontSize:12,paddingTop:2}}>Where was this? (or name the track in your message)</Text>
  <ScrollView horizontal showsHorizontalScrollIndicator={false} keyboardShouldPersistTaps="handled" contentContainerStyle={{gap:6}}>
   {tracks.map(t=>chip('t-'+t,t,where===t,()=>onWhere(where===t?null:t)))}
  </ScrollView></>}
 </View>;
}
